public final class ExchangeService {          // stateless: final fields, no setters
    private final ExchangeRateRepository rates;

    public ExchangeService(ExchangeRateRepository rates) { this.rates = rates; }

    public Money convert(Money amount, Currency target) {
        return amount.convertTo(target, rates.rateFor(amount.currency(), target));
    }
}
